570		// flattening, so fetch the complete refs rather than blobless packfiles.
571		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
572			Remote:    fetchTarget,
573			RefSpecs:  refSpecs,
574			NoTags:    true,
575			NoFilter:  true,
576			ExtraArgs: []string{"--no-write-fetch-head"},
577		}); fetchErr != nil {
