584		repo, err := OpenRepository(ctx)
585		if err != nil {
586			return fetchedRemoteRotationArchive{}, fmt.Errorf("reopen repository after fetching archived generations: %w", err)
587		}
588		tmpRefsToCleanup := archiveTmpRefs
589		defer func() {
590			cleanupFetchedArchiveTmpRefs(repo, tmpRefsToCleanup)
591		}()
592	
593		localCurrentAncestors, ok := currentGenerationAncestors(ctx, repo, localCurrentHash)
594		if !ok {
595			return fetchedRemoteRotationArchive{}, errors.New("failed to read local /full/current history")
596		}
597		for _, archive := range archives {
598			fetched, err := readFetchedRemoteRotationArchive(repo, archive)
599			if err != nil {
