601			}
602			if archiveSharesHistoryWithCurrentGeneration(ctx, repo, localCurrentAncestors, fetched.ref.Hash()) {
603				tmpRefsToCleanup = removeRef(tmpRefsToCleanup, fetched.tmpRefName)
