146		reader := bufio.NewReader(bytes.NewReader(output))
147		for i, spec := range specs {
148			result, parseErr := parseBlobBatchEntry(reader)
149			if parseErr != nil {
150				for _, s := range specs[i:] {
151					results[s] = CatFileResult{Err: parseErr}
152				}
153				break
154			}
155			results[spec] = result
156		}
157		return results
158	}
