160	func parseBlobBatchEntry(reader *bufio.Reader) (CatFileResult, error) {
161		header, err := reader.ReadString('\n')
162		if err != nil {
163			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
164		}
165		header = strings.TrimSuffix(header, "\n")
166	
167		fields := strings.Fields(header)
168		if len(fields) == 2 && fields[1] == "missing" {
169			return CatFileResult{Missing: true}, nil
170		}
171		if len(fields) != 3 {
172			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: unexpected header %q", header)
173		}
174	
175		size, err := strconv.ParseInt(fields[2], 10, 64)
176		if err != nil {
177			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: invalid size %q: %w", fields[2], err)
178		}
179		content := make([]byte, size)
180		if _, err := io.ReadFull(reader, content); err != nil {
181			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
182		}
183		separator, err := reader.ReadByte()
184		if err != nil {
185			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
186		}
187		if separator != '\n' {
188			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: unexpected separator %q", separator)
189		}
190	
191		if fields[1] != "blob" {
192			return CatFileResult{Err: fmt.Errorf("object %s is %s, want blob", fields[0], fields[1])}, nil
193		}
194		return CatFileResult{Content: content}, nil
195	}
