// topUpMatchedArchiveBlobs walks the matched archive's tree and ensures every
// referenced blob is in the local pack directory, fetching missing ones via
// `git fetch-pack`. Downstream code (updateGenerationTimestamps, the push that
// follows) reads blobs through go-git's BlobObject, which scans only the local
// pack directory and does not follow alternates. checkpoint.FetchingTree's
// blobOnDisk second-opinion would incorrectly skip blobs visible only via
// file-transport alternates, leaving go-git unable to find them, so we use a
// simpler storer-only presence check here.
func topUpMatchedArchiveBlobs(ctx context.Context, fetchTarget string, repo *git.Repository, archiveTree *object.Tree) error {
	seen := make(map[plumbing.Hash]struct{})
	var missing []string
	var walk func(t *object.Tree) error
	walk = func(t *object.Tree) error {
		for _, entry := range t.Entries {
			if entry.Mode == filemode.Dir {
				sub, err := repo.TreeObject(entry.Hash)
				if err != nil {
					return fmt.Errorf("read subtree %s: %w", entry.Name, err)
				}
				if err := walk(sub); err != nil {
					return err
				}
				continue
			}
			if _, ok := seen[entry.Hash]; ok {
				continue
			}
			seen[entry.Hash] = struct{}{}
			if repo.Storer.HasEncodedObject(entry.Hash) != nil {
				missing = append(missing, entry.Hash.String())
			}
		}
		return nil
	}
	if err := walk(archiveTree); err != nil {
		return err
	}
	if len(missing) == 0 {
		return nil
	}
	if err := remote.FetchBlobs(ctx, fetchTarget, missing); err != nil {
		return fmt.Errorf("fetch matched archive blobs: %w", err)
	}
	return nil
}

