func pushV2RefsWithRecovery(ctx context.Context, target string, refs []plumbing.ReferenceName) []v2RefPushResult {
	resultsByRef := make(map[plumbing.ReferenceName]v2RefPushResult, len(refs))
	var retryRefs []plumbing.ReferenceName

	_, initialPushSpan := perf.Start(ctx, "initial_push")
	initialResults := tryPushV2Refs(ctx, target, refs)
	initialPushSpan.End()
	for _, result := range initialResults {
		if result.err == nil {
			resultsByRef[result.refName] = result
			continue
		}
		if !errors.Is(result.err, errNonFastForward) {
			resultsByRef[result.refName] = result
			continue
		}

		shortRef := shortRefName(result.refName)
		_, syncSpan := perf.Start(ctx, "fetch_and_merge_ref", slog.String("ref", shortRef))
		syncErr := fetchAndMergeRef(ctx, target, result.refName)
		if syncErr != nil {
			syncSpan.RecordError(syncErr)
		}
		syncSpan.End()
		if syncErr != nil {
			resultsByRef[result.refName] = v2RefPushResult{
				refName: result.refName,
				err:     fmt.Errorf("couldn't sync %s: %w", shortRef, syncErr),
			}
			continue
		}
		retryRefs = append(retryRefs, result.refName)
	}

	if len(retryRefs) > 0 {
		_, retryPushSpan := perf.Start(ctx, "retry_push")
		retryResults := tryPushV2Refs(ctx, target, retryRefs)
		retryPushSpan.End()
		for _, result := range retryResults {
			if result.err != nil {
				result.err = fmt.Errorf("failed to push %s after sync: %w", shortRefName(result.refName), result.err)
			}
			resultsByRef[result.refName] = result
		}
	}

