// hasUnmigratedV1Checkpoints reports whether any v1 checkpoint has no matching
// entry in v2. Any failure opening the repo or resolving either store is
// treated as "no migration needed" so we stay silent instead of printing a
// speculative hint — the hint is advisory and should never be the reason a
// push gets noisy.
//
// Performance note: a prior implementation called v2.ListCommitted to materialize
// every v2 checkpoint, which on repos with many rotated generations took ~3s
// per pre-push and dominated pre-push latency. Instead, resolve v2 /main's
// tree once and do per-id shard lookups (O(len(v1)) tree probes) which is
// orders of magnitude cheaper.
func hasUnmigratedV1Checkpoints(ctx context.Context) bool {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return false
	}
	v1Store := checkpoint.NewGitStore(repo)
	v1List, err := v1Store.ListCommitted(ctx)
	if err != nil || len(v1List) == 0 {
		return false
	}
	v2Tree, ok := loadV2MainTree(repo)
	if !ok {
		// No reachable v2 /main means every v1 checkpoint is unmigrated.
		// Verify the first v1 entry is a real checkpoint before declaring so.
		for _, info := range v1List {
			summary, readErr := v1Store.ReadCommitted(ctx, info.CheckpointID)
			if readErr != nil || summary == nil {
				continue
			}
			return true
		}
		return false
	}
	for _, info := range v1List {
		if checkpointShardInTree(v2Tree, info.CheckpointID) {
			continue
		}
		summary, readErr := v1Store.ReadCommitted(ctx, info.CheckpointID)
		if readErr != nil || summary == nil {
			continue
		}
		return true
	}
	return false
}

// loadV2MainTree returns the v2 /main tree, or (_, false) if unreachable.
func loadV2MainTree(repo *git.Repository) (*object.Tree, bool) {
	store := checkpoint.NewV2GitStore(repo, "")
	_, treeHash, err := store.GetRefState(plumbing.ReferenceName(paths.V2MainRefName))
	if err != nil {
		return nil, false
	}
	tree, err := repo.TreeObject(treeHash)
	if err != nil {
		return nil, false
	}
	return tree, true
}

// checkpointShardInTree returns true iff the sharded path <id[:2]>/<id[2:]>
// resolves to a subtree in root. Cheap relative to listing every shard.
func checkpointShardInTree(root *object.Tree, cpID id.CheckpointID) bool {
	idStr := cpID.String()
	if len(idStr) < 3 {
		return false
	}
	shard, err := root.Tree(idStr[:2])
	if err != nil {
		return false
	}
	_, err = shard.Tree(idStr[2:])
	return err == nil
}

