func fetchRelatedRemoteRotationArchive(ctx context.Context, fetchTarget string, archives []string, localCurrentHash plumbing.Hash) (fetchedRemoteRotationArchive, error) {
	ctx, span := perf.Start(ctx, "find_related_archive", slog.Int("archive_count", len(archives)))
	defer span.End()

	refSpecs := make([]string, 0, len(archives))
	archiveTmpRefs := make([]plumbing.ReferenceName, 0, len(archives))

	for _, archive := range archives {
		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + archive)
		archiveTmpRef := archiveTmpRefName(archive)
		refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef))
		archiveTmpRefs = append(archiveTmpRefs, archiveTmpRef)
	}

	// Probe with --filter=blob:none so ancestry walking only pulls commits and
	// trees rather than every archive's blobs. Only the matched archive's blobs
	// are topped up after we pick it. On servers that don't advertise
	// uploadpack.allowFilter (or any other first-fetch error), retry without
	// the filter.
	fetch := func(extra ...string) ([]byte, error) {
		args := append([]string{"--no-write-fetch-head"}, extra...)
		return remote.Fetch(ctx, remote.FetchOptions{
			Remote:    fetchTarget,
			RefSpecs:  refSpecs,
			NoTags:    true,
			NoFilter:  true,
			ExtraArgs: args,
		})
	}
	_, probeSpan := perf.Start(ctx, "probe_fetch_blobless")
	output, fetchErr := fetch("--filter=blob:none")
	probeSpan.End()
	if fetchErr != nil {
		logging.Debug(ctx, "blobless archive probe failed; retrying without filter",
			slog.String("error", strings.TrimSpace(string(output))),
		)
		_, fallbackSpan := perf.Start(ctx, "fallback_fetch_full")
		output, fetchErr = fetch()
		fallbackSpan.End()
	}
	if fetchErr != nil {
		span.RecordError(fetchErr)
		if repo, openErr := OpenRepository(ctx); openErr == nil {
			cleanupFetchedArchiveTmpRefs(repo, archiveTmpRefs)
		}
		return fetchedRemoteRotationArchive{}, fmt.Errorf("fetch archived generations failed: %s", output)
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		span.RecordError(err)
		return fetchedRemoteRotationArchive{}, fmt.Errorf("reopen repository after fetching archived generations: %w", err)
	}
	tmpRefsToCleanup := archiveTmpRefs
	defer func() {
		cleanupFetchedArchiveTmpRefs(repo, tmpRefsToCleanup)
	}()

	_, ancestorsSpan := perf.Start(ctx, "read_local_current_ancestors")
	localCurrentAncestors, ok := currentGenerationAncestors(ctx, repo, localCurrentHash)
	ancestorsSpan.End()
	if !ok {
		err := errors.New("failed to read local /full/current history")
		span.RecordError(err)
		return fetchedRemoteRotationArchive{}, err
	}

	// Bound the ancestry walk to a hard wall-clock budget. On repos with many
	// remote archives whose history is fully disjoint from local /full/current
	// (e.g. local started as its own orphan generation), every archive takes
	// tens of milliseconds to walk, and we'd otherwise burn seconds before
	// concluding nothing matches. A future /full/root anchor will replace this
	// per-archive walk with a constant-time lookup; until then, fail fast.
	walkStart := time.Now()
	_, walkSpan := perf.Start(ctx, "walk_archive_ancestry")
	walked := 0
	for _, archive := range archives {
		if time.Since(walkStart) > rotationAncestryWalkBudget {
			break
		}
		walked++
		fetched, err := readFetchedRemoteRotationArchive(repo, archive)
		if err != nil {
			walkSpan.RecordError(err)
			walkSpan.End()
			span.RecordError(err)
			return fetchedRemoteRotationArchive{}, err
		}
		if archiveSharesHistoryWithCurrentGeneration(ctx, repo, localCurrentAncestors, fetched.ref.Hash()) {
			walkSpan.End()
			if err := topUpMatchedArchiveBlobs(ctx, fetchTarget, repo, fetched.tree); err != nil {
				span.RecordError(err)
				return fetchedRemoteRotationArchive{}, err
			}
			tmpRefsToCleanup = removeRef(tmpRefsToCleanup, fetched.tmpRefName)
			return fetched, nil
		}
	}
	walkSpan.End()
	err = errors.New("no remote archive shares history with local /full/current")
	if walked < len(archives) {
		err = fmt.Errorf("%w (walk budget exhausted after %d/%d archives)", err, walked, len(archives))
	}
	span.RecordError(err)
	return fetchedRemoteRotationArchive{}, err
}

// rotationAncestryWalkBudget caps the wall-clock spent walking remote archive
// histories looking for a shared ancestor with local /full/current. See the
// caller for rationale. Exposed as a var so tests can lower it.
var rotationAncestryWalkBudget = 1 * time.Second //nolint:gochecknoglobals // test override

