650	func topUpMatchedArchiveBlobs(ctx context.Context, fetchTarget string, repo *git.Repository, archiveTree *object.Tree) error {
651		seen := make(map[plumbing.Hash]struct{})
652		var missing []string
653		var walk func(t *object.Tree) error
654		walk = func(t *object.Tree) error {
655			for _, entry := range t.Entries {
656				if entry.Mode == filemode.Dir {
657					sub, err := repo.TreeObject(entry.Hash)
658					if err != nil {
659						return fmt.Errorf("read subtree %s: %w", entry.Name, err)
660					}
661					if err := walk(sub); err != nil {
662						return err
663					}
664					continue
665				}
666				if _, ok := seen[entry.Hash]; ok {
667					continue
668				}
669				seen[entry.Hash] = struct{}{}
670				if repo.Storer.HasEncodedObject(entry.Hash) != nil {
671					missing = append(missing, entry.Hash.String())
672				}
673			}
674			return nil
675		}
676		if err := walk(archiveTree); err != nil {
677			return err
678		}
679		if len(missing) == 0 {
680			return nil
681		}
682		if err := remote.FetchBlobs(ctx, fetchTarget, missing); err != nil {
683			return fmt.Errorf("fetch matched archive blobs: %w", err)
684		}
