// printCheckpointsV2MigrationHint prints a hint when the committed project
// settings enable checkpoints_version: 2 but the local repo has no v2 /main
// ref — i.e. migration was never run. We don't try to detect partial
// migrations: drift between v1 and v2 is acceptable post-migration and a
// strict cross-check is expensive on large repos.
func printCheckpointsV2MigrationHint(ctx context.Context) {
	checkpointsV2MigrationHintOnce.Do(func() {
		if !isCheckpointsVersion2Committed(ctx) {
			return
		}
		if v2MainRefExists(ctx) {
			return
		}
