	})
}

// v2MainRefExists reports whether refs/entire/checkpoints/v2/main is locally
// resolvable. Used as the cheap "has migration run?" probe.
func v2MainRefExists(ctx context.Context) bool {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return false
	}
	_, err = repo.Reference(plumbing.ReferenceName(paths.V2MainRefName), true)
	return err == nil
}

